UPDATE t_commission_summary
SET total_amount = total_amount + #{amount}, update_time = NOW()
WHERE openid = #{openid}

UPDATE t_commission_summary
SET pending_amount = pending_amount + #{amount}, update_time = NOW()
WHERE openid = #{openid} AND total_amount - withdrawn_amount - pending_amount >= #{amount}

UPDATE t_commission_summary
SET pending_amount = pending_amount - #{amount}, update_time = NOW()
WHERE openid = #{openid}
